package mdn.jh.automation.devices.shelly;import org.w3c.dom.Node;import mdn.jh.automation.device.DataSourceHandler;import mdn.jh.automation.io.source.DataSource;
public class ShellyDataSourceHandler extends DataSourceHandler{private static final long serialVersionUID=1L;private ShellyDevice device;public ShellyDataSourceHandler(ShellyDevice d){device=d;}public ShellyDataSourceHandler(ShellyDevice d,Node n)throws Exception{device=d;initDataComponent(n);}@Override public void update(){for(DataSource s:myDataSources){ShellyDataSource x=(ShellyDataSource)s;try{Object value=device.readInputValue(x.getComponentKey());if(value instanceof Boolean)x.updateValue((Boolean)value);else x.updateValue(((Number)value).doubleValue());}catch(Exception e){x.invalidate();}}}@Override protected String getDataSourceDetail(){return device.getName();}}
